def transform(grid):
    # Fill each hollow rectangle according to its interior size.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            ih, iw = y1 - y0 - 1, x1 - x0 - 1
            if ih <= 0 or iw <= 0:
                continue
            # 2x2 interiors use color 2; other interior sizes use 7.
            fill = 2 if ((ih == 2 and iw == 2) or ih >= 4 or iw >= 4) else 7
            for y in range(y0 + 1, y1):
                for x in range(x0 + 1, x1):
                    if grid[y][x] == bg:
                        out[y][x] = fill
    return out

